/**
 * The demo tracks, synthesised (src/audio/synth.ts): deterministic, so the WAVs in the projects
 * can be regenerated byte for byte and carry no licence but this repo's.
 *
 *   npx tsx scripts/make-music.ts            write every track
 *   npx tsx scripts/make-music.ts --check    exit 1 if a committed WAV differs from its song
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { encodeWav, synthesize, type Song } from "../src/audio/synth.js";

const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));

/**
 * example-logo: 120 bpm, a kick on every other beat — one under each material cut (beats 0, 2,
 * 4) and under the end card (beat 6) — claps on the backbeat, offbeat hats, a boom on the first hit.
 */
const logo: Song = {
  bpm: 120,
  seed: 11,
  sections: [
    {
      bars: 3,
      impact: true,
      kick: "x.......x.......",
      snare: "....x.......x...",
      hat: "..x...x...x...xo",
      chords: ["Am7", "Fmaj7", "Am7"],
      bass: [
        { step: 0, len: 6, note: "A1" },
        { step: 8, len: 6, note: "A1" },
        { step: 16, len: 6, note: "F1" },
        { step: 24, len: 6, note: "F1" },
        { step: 32, len: 12, note: "A1" },
      ],
      lead: [
        { step: 24, len: 2, note: "E5", vel: 0.7 },
        { step: 26, len: 2, note: "C5", vel: 0.6 },
        { step: 28, len: 4, note: "A4", vel: 0.8 },
      ],
    },
  ],
};

/**
 * example-beat: 124 bpm, six scenes of one bar each. An intro bar of kick and hats, a groove,
 * a riser into the morph, a boom where the card becomes the stat tile, and two last bars for the
 * mark with a kick on beats 1 and 3 (the morph lands on the second).
 */
const beat: Song = {
  bpm: 124,
  seed: 23,
  sections: [
    { bars: 1, impact: true, kick: "x...x...x...x...", hat: "..x...x...x...x.", chords: ["Am7"], bass: [{ step: 0, len: 14, note: "A1" }] },
    {
      bars: 2,
      kick: "x...x...x...x...",
      snare: "....x.......x...",
      hat: "x.xox.x.x.xox.xO",
      chords: ["Fmaj7", "C"],
      riser: true,
      bass: [
        { step: 0, len: 3, note: "F1" },
        { step: 4, len: 3, note: "F1" },
        { step: 8, len: 3, note: "F2" },
        { step: 12, len: 3, note: "F1" },
        { step: 16, len: 3, note: "C2" },
        { step: 20, len: 3, note: "C2" },
        { step: 24, len: 3, note: "C1" },
        { step: 28, len: 3, note: "E1" },
      ],
      lead: [
        { step: 2, len: 2, note: "C5", vel: 0.6 },
        { step: 6, len: 2, note: "A4", vel: 0.6 },
        { step: 10, len: 2, note: "C5", vel: 0.6 },
        { step: 14, len: 2, note: "E5", vel: 0.7 },
      ],
    },
    {
      bars: 2,
      impact: true,
      kick: "x...x...x...x...",
      snare: "....x.......x...",
      hat: "x.xox.x.x.xox.xO",
      chords: ["Dm7", "Am7"],
      bass: [
        { step: 0, len: 3, note: "D2" },
        { step: 4, len: 3, note: "D2" },
        { step: 8, len: 3, note: "D1" },
        { step: 12, len: 3, note: "F1" },
        { step: 16, len: 3, note: "A1" },
        { step: 20, len: 3, note: "A1" },
        { step: 24, len: 3, note: "A2" },
        { step: 28, len: 3, note: "G1" },
      ],
      lead: [
        { step: 16, len: 2, note: "E5", vel: 0.7 },
        { step: 18, len: 2, note: "D5", vel: 0.6 },
        { step: 20, len: 4, note: "C5", vel: 0.7 },
        { step: 26, len: 4, note: "A4", vel: 0.7 },
      ],
    },
    { bars: 2, impact: true, kick: "x.......x.......", hat: "................", chords: ["Am7", "Am7"], bass: [{ step: 0, len: 24, note: "A1" }] },
  ],
};

/** A section's bass: the chord roots on every beat of each bar (steps run on across the section's bars). */
const pulse = (roots: string[]) => roots.flatMap((note, bar) => [0, 4, 8, 12].map((step) => ({ step: bar * 16 + step, len: 3, note })));

/**
 * bench/assets/seo-agent-launch/launch.wav: 128 bpm, 21 bars (~39s), for the launch-film bench brief — long enough
 * that a ~35s film can cut its music on the end card (music.stop) instead of running out. An intro,
 * an 8-bar groove, a riser, a 6-bar drop and a half-time outro.
 */
const launch: Song = {
  bpm: 128,
  seed: 31,
  sections: [
    { bars: 2, impact: true, kick: "x...x...x...x...", hat: "..x...x...x...x.", chords: ["Am7", "Am7"], bass: [{ step: 0, len: 28, note: "A1" }] },
    {
      bars: 8,
      kick: "x...x...x...x...",
      snare: "....x.......x...",
      hat: "x.xox.x.x.xox.xO",
      chords: ["Am7", "Fmaj7", "C", "Dm7", "Am7", "Fmaj7", "C", "Dm7"],
      bass: pulse(["A1", "F1", "C2", "D2", "A1", "F1", "C2", "D2"]),
    },
    { bars: 2, riser: true, kick: "x...x...x...x...", snare: "....x...x.x.xxxx", hat: "x.x.x.x.x.x.x.x.", chords: ["Dm7", "Dm7"], bass: pulse(["D2", "D2"]) },
    {
      bars: 6,
      impact: true,
      kick: "x...x...x...x...",
      snare: "....x.......x...",
      hat: "x.xox.x.x.xox.xO",
      chords: ["Am7", "Fmaj7", "C", "Dm7", "Am7", "Fmaj7"],
      bass: pulse(["A1", "F1", "C2", "D2", "A1", "F1"]),
      lead: [
        { step: 0, len: 2, note: "E5", vel: 0.7 },
        { step: 2, len: 2, note: "C5", vel: 0.6 },
        { step: 4, len: 4, note: "A4", vel: 0.7 },
        { step: 32, len: 2, note: "E5", vel: 0.7 },
        { step: 34, len: 2, note: "D5", vel: 0.6 },
        { step: 36, len: 4, note: "C5", vel: 0.7 },
        { step: 64, len: 2, note: "E5", vel: 0.7 },
        { step: 66, len: 2, note: "C5", vel: 0.6 },
        { step: 68, len: 6, note: "A4", vel: 0.8 },
      ],
    },
    { bars: 3, impact: true, kick: "x.......x.......", hat: "..x...x...x...x.", chords: ["Am7", "Am7", "Am7"], bass: [{ step: 0, len: 44, note: "A1" }] },
  ],
};

const TRACKS: Array<{ file: string; song: Song }> = [
  { file: "bench/assets/seo-agent-launch/launch.wav", song: launch },
  { file: "projects/example-logo/assets/music.wav", song: logo },
  { file: "projects/example-beat/assets/music.wav", song: beat },
];

let stale = 0;
for (const { file, song } of TRACKS) {
  const r = synthesize(song);
  const wav = encodeWav(r.samples, r.sampleRate);
  const path = join(ROOT, file);
  if (process.argv.includes("--check")) {
    const same = existsSync(path) && Buffer.compare(readFileSync(path), wav) === 0;
    if (!same) stale++;
    console.log(`${same ? "ok   " : "STALE"} ${file}`);
    continue;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, wav);
  console.log(`${file}: ${(r.samples.length / r.sampleRate).toFixed(2)}s, ${song.bpm} bpm, ${r.beats.length} beats, ${(wav.length / 1024).toFixed(0)} KB`);
}
if (stale) process.exit(1);
